<template><section class="scr-card"><h3>{{ t('settings.compatibility') }}</h3><div class="scr-tech-grid"><span><code>minimumSupported</code>: {{ compatibility.minimumSupported || '0.39' }}</span><span><code>primaryTarget</code>: {{ compatibility.primaryTarget || '0.39' }}</span><span><code>detectedGameVersion</code>: {{ compatibility.detectedGameVersion || 'unknown' }}</span><span><code>compatibilityState</code>: {{ compatibility.compatibilityState || compatibility.state || 'unknown' }}</span><span><code>uiGeneration</code>: native-vue-runtime</span><span><code>settingsSchema</code>: {{ settings.schemaVersion }}</span></div><StatusBanner v-for="warning in compatibility.compatibilityWarnings || compatibility.warnings || []" :key="warning.code || warning" tone="warning">{{ warning.message || warning }}</StatusBanner></section></template>
<script setup>import { useStores } from "../../stores/index.js"; import StatusBanner from "../common/StatusBanner.vue"; const stores = useStores(); const compatibility = stores.compatibility.state; const settings = stores.settings.state; const { t } = stores.i18n</script>
